class Solution {
public:
    bool canBeEqual(string s1, string s2) {
        string even1 = {s1[0], s1[2]}, even2 = {s2[0], s2[2]};
        string odd1 = {s1[1], s1[3]}, odd2 = {s2[1], s2[3]};
        sort(even1.begin(), even1.end());
        sort(even2.begin(), even2.end());
        sort(odd1.begin(), odd1.end());
        sort(odd2.begin(), odd2.end());
        return even1 == even2 && odd1 == odd2;
    }
};

class Solution {
    public boolean canBeEqual(String s1, String s2) {
        char[] e1 = new char[]{s1.charAt(0), s1.charAt(2)};
        char[] e2 = new char[]{s2.charAt(0), s2.charAt(2)};
        char[] o1 = new char[]{s1.charAt(1), s1.charAt(3)};
        char[] o2 = new char[]{s2.charAt(1), s2.charAt(3)};
        Arrays.sort(e1); Arrays.sort(e2);
        Arrays.sort(o1); Arrays.sort(o2);
        return Arrays.equals(e1, e2) && Arrays.equals(o1, o2);
    }
}

/**
 * @param {string} s1
 * @param {string} s2
 * @return {boolean}
 */
var canBeEqual = function(s1, s2) {
    const e1 = [s1[0], s1[2]].sort().join('');
    const e2 = [s2[0], s2[2]].sort().join('');
    const o1 = [s1[1], s1[3]].sort().join('');
    const o2 = [s2[1], s2[3]].sort().join('');
    return e1 === e2 && o1 === o2;
};
